-- Tres casos confirmados por el propietario el 13/10/2026. Sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('anticipo-mensualidad-bonificada',$texto$Pago anticipado: una mensualidad bonificada conservando beca del 20%$texto$,'Cobranza',$texto$Preparar dos mensualidades con beca20%, revisar una mensualidad bonificada, registrar un pago completo de $800.00 y comprobar banco, adeudos, beca y comprobante familiar.$texto$,$texto$Alumno inscrito, tutor responsable financiero vigente con acceso familiar, mismo plantel/institución y moneda MXN, cuenta bancaria activa abierta antes del pago y usuario administrativo identificado con permisos. Concepto COLEGIATURA permite beca/descuento; cargos sin abonos ni recargos activos ni otro acuerdo. Fechas noviembre/diciembre2026 deben quedar dentro de inscripción/ciclo. Ejercicio de ensayo, sin dinero real; adaptar fechas/plazo si se reproduce después. Si consultas el caso ya realizado, no repetir capturas ni pagos.$texto$,$texto$ANTICIPO-TEST-03: dos originales1000, beca200 por mes. Noviembre1000-200=800; diciembre1000-200-800=0. Un pago800 liquida ambos meses; sólo noviembre recibe un abono. Banco B + $800.00 una sola vez. El propietario comunicó el folio PAG-20261013-000025; otros ensayos generan folios distintos. El propietario confirmó el caso completo; otras deudas permanecen separadas.$texto$,1,DATE '2026-10-13','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','BECA_ALUMNO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='anticipo-mensualidad-bonificada';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('anticipo-mensualidad-bonificada',1,$texto$Identificar familia, fechas y saldo bancario$texto$,$texto$Administración$texto$,$texto$Inscripciones, Tutores y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Control escolar → Inscripciones y busca al alumno; comprueba institución, plantel y vigencia que cubra noviembre/diciembre2026. Si no hay fin de inscripción, el ciclo fija el límite; en el ejemplo inicia01/10/2026 y el ciclo termina15/06/2027. 2. En Control escolar → Tutores consulta al responsable financiero activo, vínculo con el alumno y cuenta familiar. Usa ventana privada u otro navegador para el tutor, porque las pestañas normales comparten sesión. 3. Entra a Administración → Finanzas → Cuentas financieras, busca la cuenta bancaria → Aplicar filtros y anota Saldo actual como B. En el detalle comprueba Saldo actual disponible y fecha de apertura no posterior a la fecha real del pago. 4. Conserva alumno, matrícula, tutor, cuenta y B. Si el caso ya se ejecutó, consulta la evidencia existente y no alteres el saldo inicial ni registres un movimiento para prepararlo.$texto$,$texto$Saldo actual B, por ejemplo $5,000.00; comparación final B + $800.00.$texto$,$texto$Contexto identificado sin operaciones.$texto$,$texto$Git no copia datos de PostgreSQL; folios y saldos de otra BD no son evidencia de esta cuenta.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('anticipo-mensualidad-bonificada',2,$texto$Preparar el concepto exclusivo del ejemplo$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Conceptos de cobro y busca ANTICIPO-TEST-03 → Aplicar filtros. Si ya está creado para este ensayo, sólo comprueba sus opciones. 2. Para un ensayo nuevo pulsa Nuevo registro; selecciona institución, código ANTICIPO-TEST-03, nombre Prueba mensualidad bonificada y categoría Colegiatura. Si ese código pertenece a otra prueba ya utilizada, elige uno nuevo y usa ese mismo código en los pasos siguientes. 3. Activa Permite beca, Permite descuento y Concepto activo; desactiva Permite recargo para comparar resultados exactos. 4. Pulsa Crear concepto y verifica código y opciones. No reutilices cargos de otros conceptos03/04/05 en este acuerdo.$texto$,$texto$ANTICIPO-TEST-03 de categoría COLEGIATURA.$texto$,$texto$Concepto permite los ajustes de este caso.$texto$,$texto$Un concepto identifica lo que se cobra; no contiene el monto particular del alumno ni registra dinero.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('anticipo-mensualidad-bonificada',3,$texto$Asignar beca20% al concepto antes de generar$texto$,$texto$Administración$texto$,$texto$Becas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Becas por alumno → Nuevo registro; selecciona institución, plantel e inscripción del alumno. 2. Selecciona Tipo de beca activo y Concepto de cobro ANTICIPO-TEST-03. Puede usarse el mismo tipo de beca de los otros casos, pero ésta es una asignación para este concepto, no una segunda beca sobre el mismo cargo. 3. Captura Modalidad Porcentaje, Porcentaje20, Inicio01/11/2026, Fin31/12/2026, Estado Activa y Motivo y autorización: Beca del 20% para probar prueba mensualidad bonificada. 4. Pulsa Asignar beca y comprueba una sola asignación activa compatible. Si ya está registrada, no la dupliques; realiza este paso antes de emitir los adeudos.$texto$,$texto$Beca20% de1000 = $200.00 por mes.$texto$,$texto$Beca preparada para la emisión.$texto$,$texto$Crear beca después de generar no cambia automáticamente los cargos anteriores. Las tres becas del ensayo pertenecen a tres conceptos distintos.$texto$,$texto$/admin/catalogos/becas-alumno$texto$),
('anticipo-mensualidad-bonificada',4,$texto$Crear cuota mensual de noviembre y diciembre$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Crear cuota; selecciona institución, plantel, inscripción y ANTICIPO-TEST-03. 2. Captura Importe individual1000.00, MonedaMXN, Cada mes, Primer mes noviembre2026, Último mes diciembre2026 y Día límite de pago de cada mes20. 3. Selecciona Estado Activa e Incluir en generación automática de cargos. En Configuración adicional verifica desde01/11/2026 hasta31/12/2026 dentro de inscripción/ciclo. 4. Pulsa Crear cuota, revisa el resumen del modal y confirma una sola vez. Si ya existe la cuota de este ensayo, consúltala sin volver a crearla.$texto$,$texto$Dos mensualidades originales $1,000.00.$texto$,$texto$Configuración mensual sin ingreso.$texto$,$texto$La fecha límite del acuerdo es independiente de los vencimientos de noviembre/diciembre. No usar Una sola vez para estos dos meses.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('anticipo-mensualidad-bonificada',5,$texto$Generar y comprobar sólo los dos adeudos$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos; selecciona institución/contexto y Generar hasta31/12/2026. 2. Pulsa Visualizar cuotas de alumnos por aplicar; Desmarcar todos y marca únicamente noviembre/diciembre de ANTICIPO-TEST-03. Si preparaste03/04/05 juntos, puedes generar los seis una sola vez, pero el acuerdo de este caso sólo incluirá sus dos cargos. 3. Revisa original1000, beca200 y saldo800 por fila; pulsa Confirmar y generar adeudos seleccionados, revisa el modal y confirma. Si ya están emitidos, no repetir generación ni reemplazarlos. 4. Pulsa Volver a adeudos de alumnos, busca alumno/ANTICIPO-TEST-03 → Con saldo pendiente → Aplicar filtros → Ver cada mes: original1000, beca200, sin otros ajustes ni abonos y saldo800.$texto$,$texto$Dos deudas $800.00, total $1,600.00 antes del acuerdo.$texto$,$texto$Adeudos con beca identificados.$texto$,$texto$Detén el ensayo si la beca no es200 por fila. Las otras mensualidades del tutor deben quedar fuera de esta selección.$texto$,$texto$/admin/cargos/generar$texto$),
('anticipo-mensualidad-bonificada',6,$texto$Configurar el beneficio y la política de beca$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Acuerdos por pago anticipado$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado → Nueva propuesta. Selecciona institución y Tutor responsable. 2. En Buscar mensualidades de los hijos da foco para primeras diez opciones o escribe tres caracteres; agrega solamente noviembre y diciembre de ANTICIPO-TEST-03. Revisa las dos tarjetas, alumno, concepto y periodo; Quitar sólo modifica la selección. 3. En ¿Cómo se combina con la beca vigente? selecciona Conservar beca y agregar beneficio. Beneficio autorizado: Una mensualidad bonificada; Mensualidad que se bonificará: diciembre. Fecha límite para pagar completo20/10/2026 en el ejemplo: para otro ensayo elige plazo vigente y compatible con el pago real. 4. En Motivo y condiciones autorizadas captura: Se bonifica diciembre al pagar completo el acuerdo antes del 20/10/2026, conservando la beca del 20%. Ajusta también el texto del motivo si cambias el plazo. Pulsa Visualizar acuerdo y espera el desplazamiento automático al resumen.$texto$,$texto$Política Conservar beca y agregar beneficio; beneficio Una mensualidad bonificada.$texto$,$texto$Propuesta calculada sin publicar ajustes.$texto$,$texto$En Pagos recibidos → Ver → Distribución deben verse dos meses: noviembre800 y diciembre0 etiquetado Bonificada, sin abono; sólo existe ingreso800 y aplicación monetaria a noviembre. No se crea aplicación0 ficticia.$texto$,$texto$/admin/convenios-pago/anticipados/nuevo$texto$),
('anticipo-mensualidad-bonificada',7,$texto$Revisar los cálculos y guardar la propuesta$texto$,$texto$Administración$texto$,$texto$Preparar acuerdo → Así quedaría el acuerdo$texto$,$texto$1. En Así quedaría el acuerdo revisa las dos mensualidades: Noviembre: Original $1,000.00, Beca conservada $200.00, Otros ajustes $0.00, Base $800.00, Beneficio $0.00 y Pago requerido $800.00. Diciembre: Original $1,000.00, Beca conservada $200.00, Otros ajustes $0.00, Base $800.00, Beneficio $800.00 y Pago requerido $0.00. 2. Comprueba totales Base seleccionada $1600.00, Beneficio propuesto $800.00 y Pago completo requerido $800.00MXN. Si modificas campos, vuelve a Visualizar acuerdo antes de guardar. 3. Pulsa Guardar propuesta y revisa familia, meses, plazo y motivo en el modal. Cancelar sólo cierra sin guardar; si lo pruebas, vuelve a Guardar propuesta y confirma una sola vez. 4. En el detalle revisa Propuesta vigente y conserva su folio. Todavía los cargos deben800 cada mes y el banco sigue B; guardar no publica el beneficio ni modifica la beca.$texto$,$texto$Noviembre1000-200=800; diciembre1000-200-800=0. Un pago800 liquida ambos meses; sólo noviembre recibe un abono.$texto$,$texto$Propuesta guardada, saldos intactos.$texto$,$texto$El beneficio exige pago completo validado; una captura parcial normal no concede este acuerdo.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('anticipo-mensualidad-bonificada',8,$texto$Registrar un único pago completo desde el acuerdo$texto$,$texto$Administración$texto$,$texto$Detalle del acuerdo → Registrar pago completo como pendiente$texto$,$texto$1. En Convenios de pago → Acuerdos por pago anticipado busca la propuesta de ANTICIPO-TEST-03 → Ver → Registrar pago completo como pendiente. Comprueba total $800.00. 2. Selecciona Método Tarjeta, Cuenta donde se recibió el dinero bancaria cuyo saldo anotaste, Fecha y hora reales no futuras dentro del plazo y posteriores o iguales a la apertura de cuenta, y Referencia TEST-MENSUALIDAD-GRATIS-800. Tarjeta no exige archivo en este formulario; transferencia sí requiere comprobante. 3. Pulsa Registrar pago completo, revisa el modal por $800.00 y confirma una sola vez. Anota folioPAG; no captures otro pago por cada mensualidad. 4. Pulsa Ver pago. En revisión todavía no cambia el banco ni publica descuentos; el desglose de Distribución explica el beneficio condicionado. Usa el pago de este acuerdo, no un formulario ordinario desvinculado.$texto$,$texto$Referencia TEST-MENSUALIDAD-GRATIS-800; El propietario comunicó el folio PAG-20261013-000025; otros ensayos generan folios distintos.$texto$,$texto$Pago completo En revisión.$texto$,$texto$No modificar el importe para esta prueba ni activar recibido mayor. No repetir registros de un caso ya terminado.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('anticipo-mensualidad-bonificada',9,$texto$Validar y comprobar el ingreso exacto$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Desde Ver pago del acuerdo, o Administración → Finanzas → Pagos recibidos, busca el folio/referencia TEST-MENSUALIDAD-GRATIS-800 → Ver → Gestión → Control administrativo del pago. 2. Comprueba importe $800.00, institución y cuenta destino correcta; conserva el monto sin declarar dinero adicional. Revisa los meses incluidos en Distribución y vuelve a Gestión. 3. Pulsa Validar y publicar, revisa el modal y confirma una sola vez. Si pulsas Cancelar, no cambia nada; reabre y confirma cuando los datos sean correctos. Si ya aparece Validado, sólo consulta. 4. En Cuentas financieras comprueba Saldo actual B + $800.00 y un solo ingreso. En el acuerdo verifica Beneficio aplicado; ahora sí se publicaron sus ajustes junto con los abonos.$texto$,$texto$Banco B + $800.00, no un ingreso duplicado.$texto$,$texto$Pago validado, beneficio aplicado.$texto$,$texto$Un rechazo de validación por fechas o permisos no publica dinero; revisa la causa sin compensarla mediante movimiento manual. Validar desde dos pestañas sigue siendo otra prueba pendiente.$texto$,$texto$/admin/catalogos/pagos$texto$),
('anticipo-mensualidad-bonificada',10,$texto$Comprobar meses, historial, beca y portal familiar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, Acuerdo, Becas y Portal familiar$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos, busca alumno/ANTICIPO-TEST-03 → Todos o Liquidado → Aplicar filtros → Ver noviembre → Resumen e Historial; repite diciembre. Noviembre conserva BECA de200 y abono800, saldo0. Diciembre conserva BECA de200 y DESCUENTO de800, sin abono y saldo0. 2. En Pagos recibidos abre el folio → Distribución: revisa Meses incluidos en este pago y las tarjetas de abonos/bonificación. Noviembre figura800 y diciembre0 bonificado; los totales monetarios aplicados son800, no1600. En el acuerdo verifica Beneficio aplicado y en Becas por alumno20% Activa. 3. En ventana privada entra a /familias como tutor → selecciona alumno → Tus pagos; recarga: estos dos adeudos no aparecen pendientes y el historial ofrece el comprobante PDF por $800.00 en otra pestaña. Las otras deudas no se liquidan por este acuerdo. 4. Comprueba banco B+$800.00 y conserva las evidencias. El propietario confirmó todos estos resultados el13/10/2026. Deja el pago validado: no canceles ni devuelvas como parte de esta guía.$texto$,$texto$Noviembre1000-200=800; diciembre1000-200-800=0. Un pago800 liquida ambos meses; sólo noviembre recibe un abono. En Pagos recibidos → Ver → Distribución deben verse dos meses: noviembre800 y diciembre0 etiquetado Bonificada, sin abono; sólo existe ingreso800 y aplicación monetaria a noviembre. No se crea aplicación0 ficticia.$texto$,$texto$Caso completo confirmado; banco y comprobante coherentes.$texto$,$texto$No aplicar ajustes manuales ni cancelar cargos para obtener saldo0. Devolución parcial/total y duplicados/dos pestañas son ensayos separados aún no confirmados. No reutilizar el pago de este ejemplo en otra variante.$texto$,$texto$/admin/catalogos/cargos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('anticipo-sustituir-beca',$texto$Pago anticipado: sustituir la beca sólo en las mensualidades seleccionadas$texto$,'Cobranza',$texto$Preparar dos mensualidades con beca20%, revisar porcentaje adicional, registrar un pago completo de $1800.00 y comprobar banco, adeudos, beca y comprobante familiar.$texto$,$texto$Alumno inscrito, tutor responsable financiero vigente con acceso familiar, mismo plantel/institución y moneda MXN, cuenta bancaria activa abierta antes del pago y usuario administrativo identificado con permisos. Concepto COLEGIATURA permite beca/descuento; cargos sin abonos ni recargos activos ni otro acuerdo. Fechas noviembre/diciembre2026 deben quedar dentro de inscripción/ciclo. Ejercicio de ensayo, sin dinero real; adaptar fechas/plazo si se reproduce después. Si consultas el caso ya realizado, no repetir capturas ni pagos.$texto$,$texto$ANTICIPO-TEST-04: dos originales1000, beca200 por mes. Cada mes1000-200+200-100=900. Pago total1800. La compensación de beca sólo alcanza los meses del acuerdo. Banco B + $1800.00 una sola vez. Identifica el folio generado por TEST-SUSTITUCION-1800; no reutilices el folio del ejemplo03. El propietario confirmó el caso completo; otras deudas permanecen separadas.$texto$,1,DATE '2026-10-13','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','BECA_ALUMNO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='anticipo-sustituir-beca';
